from taf.hw.mcs.factory import MCSFactory
from taf.hw.mcs.executor.starter import EmptyStarter, SSHStarter


class MCSFacade(object):

    def __init__(self):
        self._factory = MCSFactory()

    def setup(self, mcs_config):
        if "vendor" not in mcs_config:
            raise Exception("vendor should be specified")

        vendor = mcs_config["vendor"]
        mcs_config.pop("vendor")

        model = None
        if "model" in mcs_config:
            model = mcs_config["model"]
            mcs_config.pop("model")

        version = None
        if "version" in mcs_config:
            version = mcs_config["version"]
            mcs_config.pop("version")

        if "starter" in mcs_config and mcs_config["starter"]:
            starter = SSHStarter(**mcs_config["starter"])
            mcs_config.pop("starter")
        else:
            starter = EmptyStarter()

        mcs = self._factory.create(vendor, model, version, starter=starter, **mcs_config)
        mcs.startup()
        mcs.connect()
        return mcs

    @staticmethod
    def teardown(mcs):
        mcs.disconnect()
        mcs.stop()

    @staticmethod
    def set_frequency(frequency, mcs, timeout=None):
        """
        set mcs frequency value
        :param frequency: frequency value
        :param mcs: mcs instance
        :param Optional[int] timeout: set frequency timeout.
        :return: execute response
        """
        return mcs.set_frequency(frequency, timeout=timeout)

    @staticmethod
    def set_phases_according_to_angles(vertical_angle, horizontal_angle,
                                       vertical_distance, horizontal_distance,
                                       output_group_id, input_group_id,
                                       mcs):
        """
        set channel phases according to vertical, horizontal angles
        :param vertical_angle: vertical angle
        :param horizontal_angle: horizontal angle
        :param vertical_distance: vertical matrix distance
        :param horizontal_distance: horizontal matrix distance
        :param output_group_id: output group id, start with 1
               e.g HBTE: output group id, B1/B2 output group id = 1
                   TopYoung: output group id equal to output id
        :param input_group_id: input group id, start with 1
               e.g HBTE: input group id, A1-A4 input group id = 1
                   TopYoung: input group id, A1/A2 input group id = 1
        :param mcs: mcs instance
        :return: execute response
        """
        return mcs.set_phases_according_to_angles(vertical_angle=vertical_angle,
                                                  horizontal_angle=horizontal_angle,
                                                  vertical_distance=vertical_distance,
                                                  horizontal_distance=horizontal_distance,
                                                  output_group_id=output_group_id,
                                                  input_group_id=input_group_id)

    @staticmethod
    def set_phase(phase, input_port, output_port, mcs):
        """
        set specified channel phase value
        :param phase: set value
        :param input_port: input port in channel
        :param output_port: output port in channel
        :param mcs: mcs instance
        :return: execute response
        """
        return mcs.set_phase(phase, input_port, output_port)

    @staticmethod
    def get_phase(input_port, output_port, mcs, **kwargs):
        """
        query specified channel phase value
        :param input_port: input port in channel
        :param output_port: output port in channel
        :param mcs: mcs instance
        :param Optional[int] timeout: read output message timeout for haojin device.
        :return: phase value
        """
        return mcs.get_phase(input_port, output_port, **kwargs)

    @staticmethod
    def set_phases(phase, begin_input_port, end_input_port, output_port, mcs):
        """
        set specified channels' phase values
        :param phase: set value
        :param begin_input_port: begin input port in channel
        :param end_input_port: end input port in channel
        :param output_port: output port in channel
        :param mcs: mcs instance
        :return: execute response
        """
        return mcs.set_phases(phase=phase,
                              begin_input_channel=begin_input_port,
                              end_input_channel=end_input_port,
                              output_channel=output_port)

    @staticmethod
    def set_attenuation(attenuation, input_port, output_port, mcs):
        """
        set specified channel attenuation value
        :param attenuation: set value
        :param input_port: input port in channel
        :param output_port: output port in channel
        :param mcs: mcs instance
        :return: execute response
        """
        return mcs.set_attenuation(attenuation, input_port, output_port)

    @staticmethod
    def get_attenuation(input_port, output_port, mcs, **kwargs):
        """
        query specified channel attenuation value
        :param input_port: input port in channel
        :param output_port: output port in channel
        :param mcs: mcs instance
        :param Optional[int] timeout: read output message timeout for haojin device.
        :return: attenuation value
        """
        return mcs.get_attenuation(input_port, output_port, **kwargs)

    @staticmethod
    def set_odd_attenuations(attenuation, begin_input_port, end_input_port, output_port, mcs):
        """
        set specified odd channel attenuation value
        :param attenuation: set value
        :param begin_input_port: begin input port in channel
        :param end_input_port: end input port in channel
        :param output_port: output port in channel
        :param mcs: mcs instance
        :return: execute response
        """
        return mcs.set_odd_attenuations(attenuation=attenuation,
                                        output_channel=output_port,
                                        begin_input_channel=begin_input_port,
                                        end_input_channel=end_input_port)

    @staticmethod
    def set_even_attenuations(attenuation, begin_input_port, end_input_port, output_port, mcs):
        """
        set specified even channel attenuation value
        :param attenuation: set value
        :param begin_input_port: begin input port in channel
        :param end_input_port: end input port in channel
        :param output_port: output port in channel
        :param mcs: mcs instance
        :return: execute response
        """
        return mcs.set_even_attenuations(attenuation=attenuation,
                                         output_channel=output_port,
                                         begin_input_channel=begin_input_port,
                                         end_input_channel=end_input_port)

    @staticmethod
    def set_matrix_number(number, mcs):
        """
        set matrix number for Topyoung device
        :param number: matrix number, 64 or 1024
        :param mcs: mcs instance
        :return: True or False indicating success or failure
        """
        return mcs.set_matrix_number(number)

    @staticmethod
    def read_matrix_number(mcs):
        """
        read matrix number for Topyoung device
        :param mcs: mcs instance
        :return: matrix number
        """
        return mcs.read_matrix_number()

    @staticmethod
    def set_position(matrix_positions, mcs):
        """
        set position for Topyoung device
        :param dict matrix_positions:
            e.g {1: [("A1", 1, 1), ("A2", 2, 2), ("A3", 1, 3)],
                 2: [("A4", 1, 1), ("A5", 2, 2), ("A6", 1, 3)]
            dict key is matrix id, 1 or 2
            dict value is positions, like List[Tuple[int, int, int]] positions: list of positions to set
                e.g [("A1", 1, 1), ("A1", 2, 2), ("A1", 1, 3)]
                where each tuple is (A port, row number, column number)
        :return: True or False indicating success or failure
        """
        return mcs.set_position(matrix_positions)

    @staticmethod
    def read_position(matrix_id, mcs):
        """
        read position for Topyoung device
        :param matrix_id: matrix id, 1 or 2
        :param mcs: mcs instance
        :return: list of positions
            e.g [("A1", 1, 1), ("A1", 2, 2), ("A1", 1, 3)]
            where each tuple is (A port, row number, column number)
        """
        return mcs.read_position(matrix_id)

    @staticmethod
    def set_aedis(matrix_id, horizontal_d_value, vertical_d_value,
                ul_horizontal_d_value, ul_vertical_d_value, mcs):
        """
        set aedis for Topyoung device
        :param matrix_id: matrix id, 1 or 2
        :param horizontal_d_value: horizontal distance value
        :param vertical_d_value: vertical distance value
        :param ul_horizontal_d_value: uplink horizontal distance value
        :param ul_vertical_d_value: uplink vertical distance value
        :param mcs: mcs instance
        :return: True or False indicating success or failure
        """
        return mcs.set_aedis(matrix_id, horizontal_d_value, vertical_d_value,
                             ul_horizontal_d_value, ul_vertical_d_value)

    @staticmethod
    def read_aedis(mcs):
        """
        read aedis for Topyoung device
        :param mcs: mcs instance
        :return: aedis value
        """
        return mcs.read_aedis()

    @staticmethod
    def set_beam(port, matrix_id, horizontal_beam_angle, vertical_beam_angle,
                 even_attenuation_enable, event_attenuation_value,
                 odd_attenuation_enable, odd_attenuation_value, mcs):
        """
        set beam parameters only available for Topyoung device.
        :param port: B port number, e.g "B1", "B2"
        :param matrix_id: matrix id, 1 or 2
        :param horizontal_beam_angle: horizontal beam angle
        :param vertical_beam_angle: vertical beam angle
        :param even_attenuation_enable: enable even channel attenuation, 0 disabled, 1 enabled
        :param event_attenuation_value: even channel attenuation value
        :param odd_attenuation_enable: enable odd channel attenuation, 0 disabled, 1 enabled
        :param odd_attenuation_value: odd channel attenuation value
        :param mcs: mcs instance
        :return: True or False indicating success or failure
        """
        return mcs.set_beam(port, matrix_id,
                            horizontal_beam_angle, vertical_beam_angle,
                            even_attenuation_enable, event_attenuation_value,
                            odd_attenuation_enable, odd_attenuation_value)
